sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.onRoomSelect = function() {};

  c.printSingleQR = function() {
    if (!c.selectedRoom) return;

    var r = c.selectedRoom;
    var printWin = window.open('', '', 'width=600,height=600');
    printWin.document.write('<html><head><title>Print Room QR</title></head><body style="text-align:center; font-family:sans-serif; padding-top:40px;">');
    printWin.document.write('<h2>' + r.hotel_name + '</h2>');
    printWin.document.write('<h1>Room ' + r.room_number + '</h1>');
    printWin.document.write('<img src="' + r.qr_image_url + '" style="width:250px; height:250px; margin:20px;"/>');
    printWin.document.write('<p>Scan this QR code with your phone camera to open Guest Services</p>');
    printWin.document.write('</body></html>');
    printWin.document.close();
    printWin.focus();
    printWin.print();
  };
};

sp_widget.css:
.panel {
  border-radius: 10px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.08);
  border: 1px solid #e3e8ee;
  overflow: hidden;
}

.panel-heading {
  background-color: #2c3e50 !important;
  color: #ffffff !important;
  padding: 15px 20px;
  border-bottom: none;
}

.panel-title {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.panel-body {
  padding: 25px;
  background-color: #ffffff;
}

.form-group label {
  font-weight: 600;
  color: #4a5568;
  font-size: 13px;
  margin-bottom: 6px;
}

.form-control {
  border-radius: 6px;
  border: 1px solid #cbd5e0;
  height: 40px;
  box-shadow: none;
}

.btn-primary {
  background-color: #3182ce;
  border-color: #3182ce;
  border-radius: 6px;
  height: 42px;
  font-size: 14px;
}

.img-thumbnail {
  border-radius: 8px;
  border: 2px solid #edf2f7;
}

.well {
  background-color: #f7fafc;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  color: #4a5568;
}

sp_widget.script:
(function() {
    data.instanceUrl = gs.getProperty('glide.servlet.uri');
    data.rooms = [];

    var roomGr = new GlideRecord('x_snc_flowops_room');
    roomGr.query();

    while (roomGr.next()) {
        // Dot-walk to x_snc_flowops_property_table
        var hotelName = roomGr.property ? roomGr.property.hotel_name.toString() : "Grand Hyatt";
        var city = roomGr.property ? roomGr.property.city.toString() : "San Diego";
        var country = "USA"; 
        var roomNum = roomGr.room_number ? roomGr.room_number.toString() : roomGr.getValue('sys_id');

        // Dot-walk to x_snc_flowops_guest
        var guestName = "Valued Guest";
        if (roomGr.current_guest && roomGr.current_guest.first_name) {
            guestName = roomGr.current_guest.first_name.toString() + " " + roomGr.current_guest.last_name.toString();
        }

        var targetUrl = data.instanceUrl + "sp?id=guest_concierge" +
            "&hotel_name=" + gs.urlEncode(hotelName) +
            "&city=" + gs.urlEncode(city) +
            "&country=" + gs.urlEncode(country) +
            "&room_id=" + gs.urlEncode(roomNum) +
            "&guest_name=" + gs.urlEncode(guestName);

        var qrImageUrl = "https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=" + gs.urlEncode(targetUrl);

        data.rooms.push({
            sys_id: roomGr.getUniqueValue(),
            room_number: roomNum,
            hotel_name: hotelName,
            city: city,
            country: country,
            guest_name: guestName,
            target_url: targetUrl,
            qr_image_url: qrImageUrl
        });
    }
})();
